function main(): void {
  console.log(Buffer.isEncoding("utf8"), Buffer.isEncoding("HEX"), Buffer.isEncoding("nope"));
  console.log(Buffer.compare(Buffer.from("a"), Buffer.from("b")), Buffer.compare(Buffer.from("b"), Buffer.from("a")), Buffer.compare(Buffer.from("a"), Buffer.from("a")));
  const b = Buffer.from([1, 2, 3, 4, 5, 6, 7, 8]);
  console.log(b.swap16().toString("hex"));
  console.log(b.swap32().toString("hex"));
  console.log(b.swap64().toString("hex"));
  console.log(URL.canParse("http://x.com"), URL.canParse("nope"));
}
